import { EmptyList } from '~/widgets/empty-list';
import { FullScreenLoading } from '~/widgets/loading/full-screen-loading';
import { useVoucherLists } from '~/entities/voucher/lib/use-voucher-lists';
import { AllVoucherItem } from '~/entities/voucher/ui/all-voucher-item';
import { VoucherType } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';

export const AllVoucherContent = () => {
  const { myVoucherList, allVoucherList, isLoading, refetchVoucherLists } = useVoucherLists();

  return (
    <>
      {isLoading && <FullScreenLoading />}
      {allVoucherList.length === 0 ? (
        <EmptyList message={i18n.t('validation:noVouchersAvailable')} reset={refetchVoucherLists} />
      ) : (
        <div className="vouc-list">
          <p className="vouc-cnt">{i18n.t('totalCount', { count: allVoucherList.length ?? 0 })}</p>
          <p className="vouc-sub-title">{i18n.t('myVoucher')}</p>
          <div className="filter-item">
            <ul>
              {myVoucherList.map((item, index) => (
                <li key={'a' + index}>
                  <AllVoucherItem item={{ ...item, type: VoucherType.내_바우처 }} />
                </li>
              ))}
            </ul>
          </div>
          <p className="vouc-sub-title">{i18n.t('others')}</p>
          <div className="filter-item">
            <ul>
              {allVoucherList
                .filter((item) => myVoucherList.findIndex((item2) => item.vouchId === item2.vouchId) === -1)
                .map((item, index) => (
                  <li key={'b' + index}>
                    <AllVoucherItem item={{ ...item, type: VoucherType.모든_바우처 }} />
                  </li>
                ))}
            </ul>
          </div>
        </div>
      )}
    </>
  );
};
